<script setup lang="ts">
import{ref}from'vue';import{useRoute,useRouter}from'vue-router';import AuthLayout from'@/layouts/AuthLayout.vue';import BaseInput from'@/components/ui/BaseInput.vue';import BaseButton from'@/components/ui/BaseButton.vue';import{useAuthStore}from'@/stores/auth';
const auth=useAuthStore(),route=useRoute(),router=useRouter(),email=ref(''),password=ref(''),loading=ref(false),error=ref('');
async function submit(){error.value='';if(!email.value.trim()||!password.value){error.value='Email và mật khẩu là bắt buộc';return}loading.value=true;try{await auth.login({email:email.value.trim(),password:password.value});const redirect=typeof route.query.redirect==='string'?route.query.redirect:'';await router.push(redirect||(auth.isAdmin?'/admin':auth.isInstructor?'/instructor/courses':'/dashboard'))}catch(e){error.value=e instanceof Error?e.message:'Đăng nhập thất bại'}finally{loading.value=false}}
</script>
<template><AuthLayout><div class="space-y-6"><div class="text-center"><h1 class="text-2xl font-extrabold">Chào mừng trở lại!</h1><p class="mt-2 text-sm text-slate-500">Đăng nhập để tiếp tục học tập</p></div><p v-if="$route.query.registered" class="rounded-xl bg-emerald-50 p-3 text-sm text-emerald-700">Đăng ký thành công. Hãy đăng nhập tài khoản mới.</p><form class="space-y-5" @submit.prevent="submit"><BaseInput id="email" v-model="email" type="email" label="Email" placeholder="ban@example.com" required/><BaseInput id="password" v-model="password" type="password" label="Mật khẩu" required/><p v-if="error" class="rounded-xl bg-red-50 p-3 text-sm text-red-700">{{error}}</p><BaseButton type="submit" :loading="loading" :full-width="true">Đăng nhập</BaseButton></form><p class="text-center text-sm">Chưa có tài khoản? <RouterLink to="/register" class="font-bold text-purple-600">Đăng ký</RouterLink></p></div></AuthLayout></template>
